import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] ans = new long[n];
        long[] st = new long[n];
        // Left-to-right pass, then right-to-left pass with the same monotonic stack.
        for (int pass = 0; pass < 2; pass++) {
            int top = 0;
            for (int k = 0; k < n; k++) {
                int i = pass == 0 ? k : n - 1 - k;
                ans[i] += top;
                while (top > 0 && st[top - 1] <= a[i]) top--;
                st[top++] = a[i];
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans[i]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	ans := make([]int64, n)
	st := make([]int64, 0, n)
	// Left-to-right pass, then right-to-left pass with the same monotonic stack.
	for pass := 0; pass < 2; pass++ {
		st = st[:0]
		for k := 0; k < n; k++ {
			i := k
			if pass == 1 {
				i = n - 1 - k
			}
			ans[i] += int64(len(st))
			for len(st) > 0 && st[len(st)-1] <= a[i] {
				st = st[:len(st)-1]
			}
			st = append(st, a[i])
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatInt(ans[i], 10))
	}
	w.WriteByte('\n')
}
